record.field:
if record.res_model == 'stock.picking' and record.res_id:
    picking = env['stock.picking'].browse(record.res_id).exists()

    if picking and picking.state not in ('done', 'cancel'):
        for move in picking.move_ids:
            if move.state in ('done', 'cancel'):
                continue

            if move.quantity != 0 or move.product_uom_qty <= 0:
                continue

            # Lấy thời điểm kích hoạt, độ chính xác microsecond
            now = datetime.datetime.now()
            seed = (
                now.hour * 3600000000
                + now.minute * 60000000
                + now.second * 1000000
                + now.microsecond
                + move.id
            )

            # Hệ số từ 0.50 đến 1.50
            ratio = 0.5 + (seed % 10001) / 10000.0

            # Quantity từ 50% đến 150% Demand
            quantity = move.product_uom_qty * ratio

            move.write({
                'quantity': quantity
            })
